import React, { useState } from 'react';
import './CayThue.css';

function CayThue() {
  const [games, setGames] = useState([
    {
      id: 1,
      name: 'Anime Vanguards',
      image: 'https://i.ytimg.com/vi/yXZpEH82wvk/hq720.jpg?sqp=-oaymwEhCK4FEIIDSFryq4qpAxMIARUAAAAAGAElAADIQj0AgKJD&rs=AOn4CLByxdkM2U4bW0HepWz6pbGOgpA6hQ',
      description: 'Game chiến đấu anime với các nhân vật nổi tiếng',
      badge: 'Thuê nhiều',
      services: [
        { name: 'Cày lvl 0 > 100', price: 120000 },
        { name: 'Cày lvl 0 > 200', price: 220000 },
        { name: 'Cày lvl 0 > 500', price: 450000 },
        { name: 'Kiếm Robux', price: 200000 }
      ]
    },
    {
      id: 2,
      name: 'Anime Crusader',
      image: 'https://frvr.com/wp-content/uploads/2025/09/roblox-anime-crusaders-codes.jpg',
      description: 'Game phiêu lưu anime với hệ thống chiến đấu độc đáo',
      badge: 'Thuê nhiều',
      services: [
        { name: 'Cày lvl 0 > 100', price: 130000 },
        { name: 'Cày lvl 0 > 200', price: 240000 },
        { name: 'Cày lvl 0 > 500', price: 500000 },
        { name: 'Mua Items hiếm', price: 300000 }
      ]
    },
    {
      id: 3,
      name: 'Universal Tower Defense',
      image: 'https://tr.rbxcdn.com/180DAY-c61bbfa00bbd9750eac5f5f482ebba3c/768/432/Image/Webp/noFilter',
      description: 'Game phòng thủ tháp với gameplay chiến thuật hấp dẫn',
      badge: 'Thuê nhiều',
      services: [
        { name: 'Cày lvl 0 > 100', price: 110000 },
        { name: 'Cày lvl 0 > 250', price: 280000 },
        { name: 'Cày lvl 0 > 500', price: 480000 },
        { name: 'Farm Tiền In-game', price: 250000 }
      ]
    },
    {
      id: 4,
      name: 'The Forge',
      image: 'https://tr.rbxcdn.com/180DAY-3eacda24071591b5157449a853e8b24c/768/432/Image/Webp/noFilter',
      description: 'Game craft và xây dựng với đồ họa đẹp mắt',
      badge: 'Thue nhiều',
      services: [
        { name: 'Cày lvl 0 > 100', price: 115000 },
        { name: 'Cày lvl 0 > 250', price: 260000 },
        { name: 'Farm Resources', price: 200000 },
        { name: 'Craft Items hiếm', price: 350000 }
      ]
    }
  ]);

  const [selectedGame, setSelectedGame] = useState(null);
  const [selectedService, setSelectedService] = useState(null);
  const [formData, setFormData] = useState({
    service: '',
    username: '',
    password: '',
    notes: ''
  });

  const handleGameClick = (game) => {
    setSelectedGame(game);
    setSelectedService(null);
    setFormData({ service: '', username: '', password: '', notes: '' });
  };

  const handleServiceClick = (service) => {
    setSelectedService(service);
    setFormData({ ...formData, service: service.name });
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!selectedGame || !selectedService || !formData.username || !formData.password) {
      alert('Vui lòng điền đầy đủ thông tin');
      return;
    }
    alert(`Đặt dịch vụ ${selectedService.name} cho game ${selectedGame.name} thành công!\nGiá: ${selectedService.price.toLocaleString('vi-VN')}đ`);
    setSelectedGame(null);
    setSelectedService(null);
    setFormData({ service: '', username: '', password: '', notes: '' });
  };

  return (
    <div className="cay-thue-container">
      <div className="cay-thue-header">
        <h1>🏴 CÀY THUÊ</h1>
        <p>Cày thể là thuê người có kỹ năng chuyên nghiệp giúp bạn hoàn thành các nhiệm vụ, cấp độ, vượt map, cày tiền, cày đồ,... mà bạn chơi mãi không qua được hoặc không có thời gian chơi Roblox.</p>
      </div>

      {!selectedGame ? (
        <div className="games-list">
          {games.map((game) => (
            <div key={game.id} className="game-card" onClick={() => handleGameClick(game)}>
              {game.badge && <div className="game-badge">{game.badge}</div>}
              <div className="game-image" style={{ backgroundImage: `url(${game.image})` }}></div>
              <h3>{game.name}</h3>
              <p>{game.description}</p>
              <button className="btn-rent">THUÊ NGAY</button>
            </div>
          ))}
        </div>
      ) : (
        <div className="cay-thue-detail">
          <button className="btn-back" onClick={() => setSelectedGame(null)}>← Quay lại</button>
          
          <h2>🔗 {selectedGame.name}</h2>
          
          <div className="detail-content">
            <div className="services-selection">
              <h3>Dịch vụ (*)</h3>
              <div className="services-list">
                {selectedGame.services.map((service, idx) => (
                  <div
                    key={idx}
                    className={`service-option ${selectedService?.name === service.name ? 'active' : ''}`}
                    onClick={() => handleServiceClick(service)}
                  >
                    <span className="service-name">{service.name}</span>
                    <span className="service-price">{service.price.toLocaleString('vi-VN')}đ</span>
                  </div>
                ))}
              </div>
            </div>

            <form onSubmit={handleSubmit} className="cay-thue-form">
              <div className="form-row">
                <div className="form-group">
                  <label>Dịch vụ (*)</label>
                  <select name="service" value={formData.service} onChange={handleInputChange} required>
                    <option value="">Chọn dịch vụ</option>
                    {selectedGame.services.map((service, idx) => (
                      <option key={idx} value={service.name}>
                        {service.name}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Thành tiền</label>
                  <input type="text" value={selectedService ? `${selectedService.price.toLocaleString('vi-VN')}đ` : '0đ'} disabled />
                </div>

                <div className="form-group">
                  <label>Thời gian hoàn thành dự kiến</label>
                  <input type="text" value="0h" disabled />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group full-width">
                  <label>Tên đăng nhập roblox (*)</label>
                  <input
                    type="text"
                    name="username"
                    value={formData.username}
                    onChange={handleInputChange}
                    placeholder="Nhập tên tài khoản Roblox"
                    required
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group full-width">
                  <label>Mật khẩu đăng nhập roblox (*)</label>
                  <input
                    type="password"
                    name="password"
                    value={formData.password}
                    onChange={handleInputChange}
                    placeholder="Nhập mật khẩu"
                    required
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group full-width">
                  <label>Công tác viên</label>
                  <select>
                    <option>Tất cả (khuyến dùng)</option>
                  </select>
                </div>
              </div>

              <div className="form-row">
                <div className="form-group full-width">
                  <label>Ghi chú đơn hàng nếu có</label>
                  <textarea
                    name="notes"
                    value={formData.notes}
                    onChange={handleInputChange}
                    placeholder="Ghi chú thêm nếu có"
                    rows="5"
                  ></textarea>
                </div>
              </div>

              <button type="submit" className="btn-submit">Lưu ý</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default CayThue;
